={title:"Gallery",url:"/gallery",icon:"Images"},$R[142]={title:"Settings",url:"/settings",icon:"Settings"},$R[143]={title:"Billing",url:"/settings/billing",icon:"CreditCard"}]},topbanner:$R[144]={text:"ChatGPT Images 2.5 and Minimax H3 are now live on Buble. Create cinematic videos and high-fidelity images in one studio. \x3Ca href='/gpt-image-2-5' class='text-primary'>Try ChatGPT Images 2.5\x3C/a> · \x3Ca href='/minimax-h3' class='text-primary'>Try MiniMax H3\x3C/a>"}},seo:$R[145]={title:"Virtual Try On | AI Clothes Try-On App | Buble",description:"Use Buble's virtual try on app to upload your photo, add a garment or outfit reference, and generate a realistic AI clothing preview before styling, shopping, or publishing.",keywords:"virtual try on, AI virtual try on, virtual try on clothes, clothes try on app, AI clothes changer, outfit preview, fashion try on",canonicalUrl:"https://buble.ai/virtual-try-on",alternateUrls:$R[146]=[$R[147]={hrefLang:"en",href:"https://buble.ai/virtual-try-on"},$R[148]={hrefLang:"zh",href:"https://buble.ai/zh/virtual-try-on"},$R[149]={hrefLang:"x-default",href:"https://buble.ai/virtual-try-on"}],imageUrl:"https://buble.ai/preview.png",appName:"Buble",locale:"en",noIndex:!1},page:$R[150]={show_sections:$R[151]=["proof","introduce","use_cases","how_to_use","source_quality","realism_limits","faq","cta"],sections:$R[152]={proof:$R[153]={block:"compare-showcase",id:"proof",label:"Before / After",title:"See a Real Virtual Try On Result Before You Upload",description:"These proof examples use the actual Buble virtual try on workflow: each person source image and garment reference image was generated as a 16:9 landscape asset, then the app produced a try-on result that is presented here as a 16:9 landscape preview.",prompt_label:"Try-on task",before_label:"Original person photo",after_label:"AI try-on result",previous_aria_label:"Previous virtual try on example",next_aria_label:"Next virtual try on example",drag_handle_aria_label:"Drag to compare the original photo and virtual try on result",items:$R[154]=[$R[155]={id:"cinematic-blazer-look-16x9",title:"Cinematic Blazer Look",prompt:"Transfer only the beige linen blazer and white blouse upper-body styling. Preserve identity, face, pose, body proportions, trousers, and clean studio presentation.",before:$R[156]={type:"image",src:"https://r2.buble.ai/uploads/generic/image/30a9489b-956c-400d-995e-50f9bfe4f23a.png",alt:"Cinematic Blazer Look 16:9 source person image before virtual try on"},after:$R[157]={type:"image",src:"https://r2.buble.ai/uploads/generic/image/75ea6ad8-f650-4de3-ad90-d9dcccbf0b01.png",alt:"Cinematic Blazer Look 16:9 AI virtual try on result"}},$R[158]={id:"burgundy-evening-dress-16x9",title:"Burgundy Evening Dress",prompt:"Apply the burgundy satin midi dress as a one-piece outfit. Keep the person recognizable, maintain natural body proportions, and keep a clean studio background.",before:$R[159]={type:"image",src:"https://r2.buble.ai/uploads/generic/image/e3fbb58b-c62f-4f19-9e4e-5d6405c6371c.png",alt:"Burgundy Evening Dress 16:9 source person image before virtual try on"},after:$R[160]={type:"image",src:"https://r2.buble.ai/uploads/generic/image/cda6312f-ccaa-47cf-9444-0936e40f4a65.png",alt:"Burgundy Evening Dress 16:9 AI virtual try on result"}},$R[161]={id:"denim-jacket-city-16x9",title:"Denim Jacket City Preview",prompt:"Replace the upper-body outfit with the light blue oversized denim jacket over a white tee. Preserve the original sidewalk background, face, pose, pants, and natural lighting.",before:$R[162]={type:"image",src:"https://r2.buble.ai/uploads/generic/image/f5d98d6f-b514-4b4c-bdb2-917df7ecf0ce.png",alt:"Denim Jacket City Preview 16:9 source person image before virtual try on"},after:$R[163]={type:"image",src:"https://r2.buble.ai/uploads/generic/image/6bb2f1fe-6e1b-4be8-90c2-9e94ffe32dea.png",alt:"Denim Jacket City Preview 16:9 AI virtual try on result"}},$R[164]={id:"sage-athleisure-set-16x9",title:"Sage Athleisure Set",prompt:"Transfer the sage green hoodie and jogger athleisure set as a full visible outfit. Preserve the person, hands, pose, proportions, and studio realism.",before:$R[165]={type:"image",src:"https://r2.buble.ai/uploads/generic/image/edd70391-eb78-4421-98d5-4329424d1b23.png",alt:"Sage Athleisure Set 16:9 source person image before virtual try on"},after:$R[166]={type:"image",src:"https://r2.buble.ai/uploads/generic/image/78668111-9d6c-4719-ac46-359f190d81d8.png",alt:"Sage Athleisure Set 16:9 AI virtual try on result"}},$R[167]={id:"camel-trench-layer-16x9",title:"Camel Trench Layer",prompt:"Add the camel trench coat as an outer layer over the existing outfit. Preserve the original indoor background, face, hair, jeans, shoes, and natural lighting.",before:$R[168]={type:"image",src:"https://r2.buble.ai/uploads/generic/image/d0808b44-df8b-4c85-8ced-34a534f93cd3.png",alt:"Camel Trench Layer 16:9 source person image before virtual try on"},after:$R[169]={type:"image",src:"https://r2.buble.ai/uploads/generic/image/229a2733-259d-4649-81f7-3ecf9ea54fd8.png",alt:"Camel Trench Layer 16:9 AI virtual try on result"}}]},introduce:$R[170]={block:"features",id:"introduce",label:"Overview",title:"What Is Virtual Try On in Buble?",description:"Virtual try on is an image-to-image app for previewing clothes on a person photo. Upload a clear photo of the person, add a garment product image or a target model outfit reference, then generate a new image that shows how the clothing direction could look on that person. It is built for fast visual decisions, not for replacing size charts, tailoring, or a physical fitting.",items:$R[171]=[$R[172]={title:"Person Photo + Outfit Reference",description:"The app uses two required image inputs: your photo and a garment or target-model reference. The reference can be a clothing product image, a flat lay, or another model wearing the outfit.",icon:"Images"},$R[173]={title:"Choose the Garment Scope",description:"Control whether the virtual try on should replace the full visible outfit, only the upper body, lower body, a dress or one-piece garment, or a visible layer or accessory.",icon:"Shirt"},$R[174]={title:"Keep or Clean the Background",description:"Use the keep-background option when you want to preserve the original photo context, or choose a clean studio background when the result needs a simpler product-style presentation.",icon:"PanelsTopLeft"},$R[175]={title:"Designed for Realistic Preview Images",description:"The prompt asks the model to preserve identity, pose, skin tone, camera angle, and non-clothing areas while transferring garment color, texture, silhouette, and layering from the reference.",icon:"Sparkles"},$R[176]={title:"Works Best as a Styling Draft",description:"Use virtual try on to compare outfit direction, prepare product visuals, plan a wardrobe look, or test an ecommerce creative before committing to a shoot or purchase.",icon:"ScanSearch"},$R[177]={title:"Review Before Publishing",description:"AI try-on output can still misread fabric, occlusion, logos, scale, or body contact. Treat the result as a visual preview and review details before using it in commercial content.",icon:"BadgeCheck"}]},use_cases:$R[178]={block:"use-cases-sticky-cards",id:"use_cases",label:"Use Cases",title:"Where a Virtual Try On App Is Most Useful",description:"People search for virtual try on when they already have a person photo, a garment image, or a shopping idea and need to see a believable visual preview. These are the jobs the Buble app is designed to support.",items:$R[179]=[$R[180]={title:"Ecommerce Product Preview",description:"Turn a garment product photo into an on-person preview for marketplace tests, lookbook drafts, product page concepts, or ad creative planning before booking a model shoot.",icon:"ShoppingBag",image:$R[181]={src:"https://r2.buble.ai/uploads/generic/image/9b8d72ab-5920-4d97-94fe-6f3a00cabc2e.png",alt:"Ecommerce Product Preview 16:9 virtual try on example generated with Buble"}},$R[182]={title:"Personal Outfit Planning",description:"Try an outfit direction on your own photo before buying, packing, styling a look, or deciding whether a color, silhouette, or layering choice fits the image you want.",icon:"UserRound",image:$R[183]={src:"https://r2.buble.ai/uploads/generic/image/682584bb-7f00-4637-8ce7-e3c76badddbb.png",alt:"Personal Outfit Planning 16:9 virtual try on example generated with Buble"}},$R[184]={title:"Fashion Design Mockups",description:"Use sketches, AI-generated clothing concepts, flat lays, or product references to create early try-on previews for design review, mood boards, and collection planning.",icon:"Palette",image:$R[185]={src:"https://r2.buble.ai/uploads/generic/image/08d19150-46d7-4feb-a558-08e76426e207.png",alt:"Fashion Design Mockups 16:9 virtual try on example generated with Buble"}},$R[186]={title:"Creator and Social Shopping Content",description:"Generate a fast outfit preview for social polls, styling advice, affiliate content, or before-and-after posts where viewers need to understand the clothing change quickly.",icon:"Share2",image:$R[187]={src:"https://r2.buble.ai/uploads/generic/image/fc351099-12a0-428d-9de8-528c5b1a1346.png",alt:"Creator and Social Shopping Content 16:9 virtual try on example generated with Buble"}}]},how_to_use:$R[188]={block:"features-step",id:"how_to_use",label:"How To Use",title:"How to Use Virtual Try On in Buble",description:"The generator above is the actual virtual try on app. Keep the workflow simple: start with a usable person photo, add a clear clothing reference, choose the garment scope, then inspect the result before using it.",items:$R[189]=[$R[190]={title:"Upload the Person Photo",description:"Use a clear full-body or half-body photo when possible. Good lighting, visible body shape, and minimal occlusion around the clothing area give the model more reliable context.",icon:"Upload"},$R[191]={title:"Add the Garment or Outfit Reference",description:"Upload a product image, flat lay, or model outfit reference. The cleaner the garment shape, color, pattern, and texture, the easier it is for the virtual try on app to transfer the right style.",icon:"Images"},$R[192]={title:"Choose Scope and Background",description:"Select the garment scope, such as full visible outfit, top, bottom, dress, or layer. Keep the original background for a personal photo feel, or use the studio option for a cleaner preview.",icon:"SlidersHorizontal"},$R[193]={title:"Generate, Review, and Iterate",description:"Check whether the output preserved the person, transferred the intended clothing details, and handled hands, hair, shadows, folds, and edges naturally. If not, try a clearer source or reference image.",icon:"SearchCheck"}],sticky_feature:$R[194]={timeline_step_vh:56,desktop_min_width:1024}},source_quality:$R[195]={block:"features",id:"source_quality",label:"Input Guide",title:"Photo and Garment Inputs That Work Better",description:"Virtual try on quality depends heavily on the source material. The app accepts common image files for both required inputs, and the current configuration allows JPG, PNG, and WebP images up to 10 MB per input.",items:$R[196]=[$R[197]={title:"Use a Photo You Have Permission to Edit",description:"Only upload your own photo or a photo you have permission to use. This matters for privacy, consent, and commercial publishing rights.",icon:"ShieldCheck"},$R[198]={title:"Prefer Good Lighting and Visible Body Shape",description:"A clear full-body or half-body image with fitted clothing usually works better than a dark, cluttered, far-away, seated, or heavily cropped photo.",icon:"SunMedium"},$R[199]={title:"Avoid Blocking the Clothing Area",description:"Hands, bags, hair, crossed arms, props, and oversized clothing can make it harder to place the new garment cleanly on the body.",icon:"ScanLine"},$R[200]={title:"Use a Clear Garment Reference",description:"Product photos, flat lays, or model photos with visible color, pattern, neckline, sleeves, length, and silhouette give the app better information than tiny or cropped references.",icon:"FileImage"},$R[201]={title:"Tell the App What to Preserve",description:"Use the extra direction field for constraints such as keeping shoes unchanged, preserving hairstyle, making a jacket oversized, or focusing only on the upper-body garment.",icon:"FilePenLine"},$R[202]={title:"Use Studio Background for Cleaner Product Looks",description:"If the original room or street scene distracts from the clothing, choose the clean studio background option to make the try-on result easier to review.",icon:"Sparkles"}]},realism_limits:$R[203]={block:"features",id:"realism_limits",label:"Accuracy",title:"What Virtual Try On Can and Cannot Promise",description:"A credible virtual try on page should be honest about limits. AI can create a useful visual preview, but it is still an image generation task, not a measurement system or guaranteed fit prediction.",items:$R[204]=[$R[205]={title:"It Is Not a Size Recommendation",description:"The generated image can help you judge visual style, but it does not prove the garment size, tailoring, fabric stretch, or real-world comfort. Use merchant size charts and product details for sizing.",icon:"Ruler"},$R[206]={title:"Garment Details Can Change",description:"Small logos, text, buttons, seams, textures, and patterns may be simplified or changed. Review important brand or product details before publishing.",icon:"ZoomIn"},$R[207]={title:"Occlusion Is Hard",description:"Hands, hair, bags, jewelry, loose layers, and complex poses are common sources of artifacts because the model must decide which pixels belong in front of the new garment.",icon:"Layers"},$R[208]={title:"Use It as a Decision Aid",description:"The best use of virtual try on is to compare style direction, color, silhouette, and presentation before committing to a purchase, shoot, listing, or campaign asset.",icon:"GitCompare"}]},faq:$R[209]={block:"faq",id:"faq",label:"FAQ",title:"Virtual Try On Questions People Ask Before Uploading",description:"These answers focus on the current Buble app behavior and the practical concerns that usually decide whether a virtual try on result is useful.",items:$R[210]=[$R[211]={question:"What does virtual try on mean?",answer:"Virtual try on means generating a visual preview of clothing on a person without physically wearing the garment. In Buble, you upload a person photo and an outfit or garment reference, then the app creates a new image showing the clothing direction on that person."},$R[212]={question:"What images can I upload?",answer:"The current app is configured for image inputs. It accepts JPG, PNG, and WebP files up to 10 MB for the person photo and the garment or outfit reference."},$R[213]={question:"Can I use a model photo as the outfit reference?",answer:"Yes. The reference can be a garment product image, flat lay, or another model wearing the outfit. When using a model photo, the prompt tells the app to use the clothing rather than copying that person's identity, pose, hair, or background."},$R[214]={question:"Does virtual try on guarantee real fit or sizing?",answer:"No. It is a visual AI preview, not a measurement or fit-guarantee system. Use the result to judge style, color, silhouette, and presentation, then rely on size charts, product details, and reviews for real fit decisions."},$R[215]={question:"Why did my try-on result look wrong?",answer:"Common causes include poor lighting, a cropped or seated pose, hands or hair covering the clothing area, an unclear garment reference, heavy occlusion, or asking the model to change too many things at once. Try a clearer person photo and a cleaner clothing reference."},$R[216]={question:"Can I keep the original background?",answer:"Yes. The app has a keep-background option for preserving the original setting, perspective, and lighting. It also includes a clean studio option when you want a simpler product-style result."},$R[217]={question:"Can I use virtual try on for ecommerce content?",answer:"You can use it for product-preview drafts, lookbook concepts, social content, and creative planning when you have the rights to the person photo and garment reference. Always review the final image before using it in ads, listings, or paid campaigns."},$R[218]={question:"Is the output an image or a video?",answer:"This Buble virtual try on app outputs an image. The current flow is configured for a 1K, 3:4 image result."}]},cta:$R[219]={block:"cta",id:"cta",label:"Start",title:"Create a Virtual Try On Preview from Your Own Photo",description:"Upload a person photo, add a garment or outfit reference, and generate a realistic AI clothing preview with the Buble virtual try on app.",buttons:$R[220]=[$R[221]={title:"Start virtual try on",url:"/virtual-try-on",variant:"default",size:"lg",icon:"Sparkles"}]}}},models:$R[222]=[$R[223]={id:"0ec178dc-8562-4fdf-98fc-9c26c368e2c3",key:"alibaba/happyhorse-1.1",name:"Happy Horse 1.1",provider:"Alibaba",mediaType:"video",vendorId:"813865ca-b06d-4b09-a4f6-627e49eb37c2",version:"1.1",icon:"https://r2.buble.ai/uploads/9468f761e23dd9f477634e00fd6f3022.svg",coverImage:void 0,coverVideo:void 0,coverPoster:void 0,coverAlt:"Happy Horse 1.1 AI video generation example",description:"Generate Happy Horse 1.1 videos from text prompts, first-frame images, or 1-9 reference images with 720P/1080P and 3-15 second controls.",slug:"happy-horse-ai-video-generator",isDefault:!0,status:"active",pricing:$R[224]={type:"duration_based",per_second:1,minimum_charge:1,duration_source:"options.duration",duration_rounding:"ceil",multipliers:$R[225]={resolution:$R[226]={"720P":8,"1080P":12}}},configSchemaVersion:1,configVersion:2,configHash:"sha256:b9c3ec6ce2c1cedc86a00bc3ca9af6df6eced9c2fbb93d598d2da547c2fdc1a1",configMeta:$R[227]={schema_version:1,config_hash:"sha256:b9c3ec6ce2c1cedc86a00bc3ca9af6df6eced9c2fbb93d598d2da547c2fdc1a1",sections:$R[228]={capabilities:$R[229]={kind:"media_model.capabilities.v1",schema_vers